import java.util.*;

public class Main {
    static int numIdenticalPairs(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        int result = 0;
        for (int x : nums) {
            result += counts.getOrDefault(x, 0);      // pairs with every earlier occurrence
            counts.merge(x, 1, Integer::sum);
        }
        return result;
    }
}

